function resultArray(nums) {
  const sorted = [...new Set(nums)].sort((a, b) => a - b);
  const rank = new Map();
  sorted.forEach((value, index) => rank.set(value, index + 1));
  const size = sorted.length;
  const tree1 = new Array(size + 1).fill(0);
  const tree2 = new Array(size + 1).fill(0);
  const add = (tree, index) => {
    while (index <= size) {
      tree[index]++;
      index += index & -index;
    }
  };
  const countUpTo = (tree, index) => {
    let total = 0;
    while (index > 0) {
      total += tree[index];
      index -= index & -index;
    }
    return total;
  };

  const arr1 = [nums[0]];
  const arr2 = [nums[1]];
  add(tree1, rank.get(nums[0]));
  add(tree2, rank.get(nums[1]));
  for (let i = 2; i < nums.length; i++) {
    const value = nums[i];
    const position = rank.get(value);
    const greater1 = arr1.length - countUpTo(tree1, position);
    const greater2 = arr2.length - countUpTo(tree2, position);
    if (greater1 > greater2 || (greater1 === greater2 && arr1.length <= arr2.length)) {
      arr1.push(value);
      add(tree1, position);
    } else {
      arr2.push(value);
      add(tree2, position);
    }
  }
  return arr1.concat(arr2);
}

