function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = [1e9, 1000, 20][int(0, 2)];
    return [Array.from({ length: 2000 }, () => int(1, top))];
  }
  const n = int(3, 10);
  const top = [3, 8, 1e9][int(0, 2)];
  return [Array.from({ length: n }, () => int(1, top))];
}
